/* Flash cards USMLE: Hematology & Oncology (462 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["hematology-and-oncology"] = [{"name":"Anatomy","cards":[["1oo14drsp","What is the most abundant leukocyte in blood?","Neutrophils (about 40-70% of leukocytes).","Neutrófilos."],["8ldrg3v4a","Mnemonic for relative leukocyte abundance?","Neutrophils Like Making Everything Better: neutrophils > lymphocytes > monocytes > eosinophils > basophils.","Ordem de abundância dos leucócitos."],["rttvcp5yu","What do erythrocytes lack and how do they make energy?","No nucleus or mitochondria; rely on anaerobic glycolysis (and HMP shunt for NADPH).","Sem núcleo e mitocôndria; glicólise anaeróbia."],["18zk9az1x","What is the lifespan of an erythrocyte?","About 120 days.","120 dias."],["12n36pfoy","What is the shape of an erythrocyte and why?","Biconcave disc, increasing surface area for gas exchange and flexibility.","Disco bicôncavo."],["1ckkgwc1m","How do erythrocytes export CO2?","As bicarbonate via the chloride-bicarbonate exchanger (chloride shift).","Como bicarbonato trocado por cloreto."],["5nzbup1a1","What are reticulocytes?","Immature RBCs that still contain RNA (bluish on Wright stain); reflect marrow erythropoiesis.","Hemácias jovens; refletem a medula."],["119t7lu1u","What does an elevated reticulocyte count indicate?","Marrow response to blood loss or hemolysis.","Resposta à perda ou hemólise."],["1xtxjq81j","What is the lifespan of a platelet?","About 8-10 days.","8 a 10 dias."],["azesl42j5","Where are platelets derived from?","Fragments of megakaryocytes in the bone marrow.","Fragmentos de megacariócitos."],["194zwgfuv","What fraction of platelets is stored in the spleen?","About one-third.","Um terço no baço."],["1n23ro6c5","What do platelet dense granules contain?","ADP and Ca2+ (also serotonin).","ADP e cálcio."],["fy732zvb1","What do platelet alpha granules contain?","von Willebrand factor, fibrinogen, fibronectin, platelet factor 4.","Fator de von Willebrand e fibrinogênio."],["1iz0uu9nn","What platelet receptor binds von Willebrand factor?","GpIb.","GpIb."],["1kt046v13","What platelet receptor binds fibrinogen for aggregation?","GpIIb/IIIa.","GpIIb/IIIa."],["tnklst1ng","What is the appearance of neutrophils?","Multilobed nucleus (3-5 lobes) with specific granules.","Núcleo multilobulado."],["z781n8hs4","What do neutrophil specific granules contain?","Leukocyte alkaline phosphatase, collagenase, lysozyme, lactoferrin.","Fosfatase alcalina leucocitária e lisozima."],["1ttfb001c","What do neutrophil azurophilic granules contain?","Myeloperoxidase, proteinases, cathepsin G, defensins, lysozyme.","Mieloperoxidase."],["291c9biqy","What do hypersegmented neutrophils indicate?","Megaloblastic anemia (B12 or folate deficiency).","Deficiência de B12 ou folato."],["bmtune8hf","What are band cells and when do they increase?","Immature neutrophils; increase in bacterial infections (left shift).","Bastões; desvio à esquerda."],["89afqa162","What chemotactic agents attract neutrophils?","C5a, IL-8, LTB4, kallikrein, platelet-activating factor, N-formylmethionine.","C5a, IL-8, LTB4."],["1dywf4v2i","What is the appearance of monocytes?","Large, kidney-shaped nucleus with frosted glass cytoplasm.","Núcleo em rim e citoplasma em vidro fosco."],["1dj4nuo16","What do monocytes differentiate into?","Macrophages in tissues.","Macrófagos."],["eaozuok0x","What activates macrophages?","IFN-gamma (from Th1 cells).","IFN-gama."],["cnlvo9doh","What is the lipid A receptor on macrophages?","CD14 with TLR4 (binds LPS of gram-negative bacteria), causing septic shock.","CD14 e TLR4 reconhecem LPS."],["rw1vdkw8i","What are the functions of eosinophils?","Defense against helminths (major basic protein), modulation of allergic reactions (histaminase).","Combatem helmintos e alergia."],["masgau11h","What causes eosinophilia?","Parasites, asthma, allergic processes, chronic adrenal insufficiency, drugs, neoplasia (Hodgkin), Churg-Strauss.","Parasitas, alergia, Addison, neoplasias."],["16wwimtkb","What is the appearance of basophils?","Bilobed nucleus with densely basophilic granules containing heparin and histamine.","Grânulos de histamina e heparina."],["1hby8w313","What does basophilia suggest?","Myeloproliferative disease, especially CML.","Doença mieloproliferativa, sobretudo LMC."],["1scyf541c","What are mast cells and how are they activated?","Tissue cells similar to basophils; IgE cross-linking causes degranulation releasing histamine, heparin, tryptase, eosinophil chemotactic factors.","Mastócitos degranulam com IgE."],["1lnjq986w","Which drug prevents mast cell degranulation?","Cromolyn sodium.","Cromoglicato."],["14vu0rh1y","What are dendritic cells?","Professional antigen-presenting cells in tissues (Langerhans cells in skin) that express MHC II and B7 and migrate to lymph nodes.","Células apresentadoras de antígeno profissionais."],["1oj10ur1f","What is the appearance of lymphocytes?","Round, densely staining nucleus with small amount of pale cytoplasm.","Núcleo redondo e pouco citoplasma."],["r0yppt1pi","Where do B cells mature?","Bone marrow.","Medula óssea."],["1awvjbx4a","Where do T cells mature?","Thymus.","Timo."],["a6gvchd1h","What are plasma cells?","Antibody-producing differentiated B cells with clock-face chromatin and abundant RER; off-center nucleus.","Plasmócitos produzem anticorpos."],["i9u9brdaq","Which malignancy involves plasma cells?","Multiple myeloma.","Mieloma múltiplo."],["a7q87txzg","What are the main components of the spleen?","Red pulp (sinusoids, filtering old RBCs) and white pulp (lymphoid tissue: B cells in follicles, T cells in periarteriolar lymphoid sheath).","Polpa vermelha filtra; polpa branca é linfoide."],["15f1fs146","What happens after splenectomy?","Increased risk of encapsulated bacteria infections; Howell-Jolly bodies, target cells, thrombocytosis, lymphocytosis.","Risco de bactérias encapsuladas; corpúsculos de Howell-Jolly."],["1bpf2rv1g","Which encapsulated organisms threaten asplenic patients?","Streptococcus pneumoniae, Haemophilus influenzae type b, Neisseria meningitidis, Salmonella, Klebsiella, group B strep.","Pneumococo, Haemophilus e meningococo."],["1erfuxz1t","What vaccines are given before splenectomy?","Pneumococcal, Hib, and meningococcal vaccines.","Pneumococo, Hib e meningococo."],["1pafdg71m","What is the composition of normal adult hemoglobin?","HbA: alpha2 beta2.","Duas alfa e duas beta."],["1j3awdycu","What is the composition of fetal hemoglobin?","HbF: alpha2 gamma2.","Duas alfa e duas gama."],["1xxcbdpr4","What is the hematocrit's normal range?","Men about 41-53%, women about 36-46%.","Homens 41-53%, mulheres 36-46%."],["1101eptln","What is the role of erythropoietin?","Hormone from kidney peritubular interstitial cells, stimulating RBC production in response to hypoxia.","Hormônio renal que estimula hemácias."],["7t3vjjbph","What is the role of thrombopoietin?","Liver-produced hormone that stimulates megakaryocyte and platelet production.","Hormônio hepático que estimula plaquetas."],["en28ji6el","Where does hematopoiesis occur in adults?","Bone marrow of axial skeleton (vertebrae, sternum, ribs, pelvis) and proximal long bones.","Medula do esqueleto axial."],["1x8h2w3uz","What is extramedullary hematopoiesis?","Blood cell production outside marrow (liver, spleen) in severe anemia or myelofibrosis; causes hepatosplenomegaly.","Produção fora da medula; baço e fígado."],["1t6fojt2c","What is the precursor of all blood cells?","Hematopoietic stem cell (CD34+).","Célula-tronco CD34+."],["1mfohx1gf","What is the cell lineage of granulocytes?","Myeloblast to promyelocyte to myelocyte to metamyelocyte to band to segmented neutrophil.","Mieloblasto até neutrófilo segmentado."]]},{"name":"Pathology (Part 1)","cards":[["9xdmlz546","What defines microcytic anemia?","MCV <80 fL.","VCM abaixo de 80."],["1elnm0g1m","Causes of microcytic anemia?","Iron deficiency (late), anemia of chronic disease (late), thalassemias, lead poisoning, sideroblastic anemia.","Ferropriva, doença crônica, talassemia, chumbo, sideroblástica."],["1ueye0yn6","Most common cause of iron deficiency in adult men and postmenopausal women?","Chronic GI blood loss (e.g., colon cancer); requires GI evaluation.","Perda gastrointestinal; investigar câncer."],["11bq8vsty","Most common cause of iron deficiency in premenopausal women?","Menstrual blood loss.","Perda menstrual."],["10f4z0k1n","Lab findings in iron deficiency anemia?","Low iron, high TIBC/transferrin, low ferritin, low transferrin saturation, high RDW, microcytic hypochromic RBCs.","Ferritina baixa e transferrina alta."],["dezqk21xy","What are signs specific to iron deficiency?","Pica, koilonychia (spoon nails), angular cheilitis, glossitis, restless legs.","Pica, unhas em colher, queilite."],["nmo8r31u3","What is Plummer-Vinson syndrome?","Iron deficiency anemia, esophageal webs, and atrophic glossitis.","Anemia ferropriva, membranas esofágicas e glossite."],["9ms0tq1cd","What is alpha thalassemia?","Deletion of alpha-globin genes on chromosome 16; reduced alpha-chain synthesis.","Deleção de genes alfa no cromossomo 16."],["1twgkump3","What is the alpha thalassemia trait (2-gene deletion)?","Mild microcytic anemia; cis deletion (same chromosome) more common in Asians with higher risk of severe disease in offspring; trans deletion in Africans.","Anemia microcítica leve."],["1aeeadc1b","What is hemoglobin H disease?","3 alpha-globin gene deletions: excess beta chains form HbH (beta4); moderate to severe hemolytic anemia.","HbH com três deleções; hemólise."],["1wkvlle1l","What is hemoglobin Barts?","4 alpha-gene deletions: gamma4 tetramers; hydrops fetalis, incompatible with life.","Quatro deleções; hidropisia fetal."],["rzrtyg1gw","What is beta thalassemia?","Point mutations in splice sites or promoter of beta-globin gene (chromosome 11) causing decreased beta chains; common in Mediterranean populations.","Mutações do gene beta no cromossomo 11."],["knqtzz15u","What is beta thalassemia minor?","Heterozygote: mild microcytic anemia, increased HbA2 (>3.5%).","Traço beta: HbA2 elevada."],["kszc2b15z","What is beta thalassemia major?","Homozygote: severe anemia after 6 months (when HbF declines), requiring transfusions; crew-cut skull, chipmunk facies (marrow expansion), hepatosplenomegaly, iron overload.","Anemia grave com transfusões; face de esquilo."],["1qhbsy019","Why does beta thalassemia major present after 6 months of age?","Fetal hemoglobin (no beta chains) protects the infant until it declines.","HbF protege até os 6 meses."],["93q0k216n","What is the Mentzer index?","MCV/RBC count; <13 suggests thalassemia, >13 suggests iron deficiency.","VCM/hemácias <13 sugere talassemia."],["1ee592opf","What are target cells associated with?","HbC disease, asplenia, liver disease, thalassemia.","Hemoglobina C, asplenia, hepatopatia, talassemia."],["16a0wmp10","What is lead poisoning's effect on heme synthesis?","Inhibits ferrochelatase and ALA dehydratase; increased protoporphyrin and ALA.","Inibe ferroquelatase e ALA desidratase."],["1jj0z8hgt","What is sideroblastic anemia?","Defective protoporphyrin synthesis causing iron trapped in mitochondria; ringed sideroblasts; high iron and ferritin, normal or low TIBC.","Ferro preso nas mitocôndrias; sideroblastos em anel."],["cueosqeqm","Causes of sideroblastic anemia?","Congenital ALAS2 defect (X-linked), alcohol, lead, B6 deficiency (isoniazid), copper deficiency, myelodysplasia.","Álcool, chumbo, falta de B6, cobre."],["18iwygycv","Treatment of congenital sideroblastic anemia?","Pyridoxine (B6).","Piridoxina."],["leknnjgld","What defines macrocytic anemia?","MCV >100 fL.","VCM acima de 100."],["w1ff56f8t","What is megaloblastic anemia?","Impaired DNA synthesis causing nuclear-cytoplasmic asynchrony: macrocytosis, hypersegmented neutrophils, glossitis.","Falha na síntese de DNA; neutrófilos hipersegmentados."],["rr5id41lp","Causes of nonmegaloblastic macrocytic anemia?","Alcoholism, liver disease, hypothyroidism, reticulocytosis, drugs.","Álcool, hepatopatia, hipotireoidismo."],["q68tzy16i","How is folate deficiency distinguished from B12 deficiency?","Both have high homocysteine; only B12 deficiency has high methylmalonic acid and neurologic symptoms.","Só a falta de B12 eleva ácido metilmalônico e dá sintomas neurológicos."],["1a21zc61a","What is pernicious anemia?","Autoimmune gastritis with antibodies against parietal cells and intrinsic factor, causing B12 deficiency.","Gastrite autoimune com falta de B12."],["jemw4d1fm","What is orotic aciduria's anemia?","Megaloblastic anemia unresponsive to B12/folate, with orotic acid in urine; treated with uridine.","Megaloblástica que não melhora com B12/folato."],["1a0po6a43","What is Diamond-Blackfan anemia?","Congenital pure red cell aplasia from defective ribosomal proteins: macrocytic anemia in infancy, short stature, thumb abnormalities (triphalangeal).","Aplasia eritroide congênita; anomalias do polegar."],["e77q3i1et","What are the causes of normocytic anemia?","Hemolysis (increased reticulocytes) or underproduction: anemia of chronic disease, aplastic anemia, CKD, early iron deficiency.","Hemólise ou baixa produção."],["1c62r82ox","What is anemia of chronic disease?","Inflammation increases hepcidin, decreasing iron release from macrophages and absorption: low iron, low TIBC, high ferritin.","Inflamação aumenta hepcidina; ferritina alta."],["1un1wdrba","Treatment of anemia of chronic disease?","Treat the underlying disease; ESAs in CKD or chemotherapy.","Tratar a doença de base."],["17fs0j89h","What is aplastic anemia?","Failure or destruction of hematopoietic stem cells: pancytopenia with hypocellular fatty marrow.","Medula vazia; pancitopenia."],["a47533kjr","Causes of aplastic anemia?","Radiation, drugs (chloramphenicol, benzene, alkylating agents, antimetabolites), viruses (parvovirus B19, EBV, HIV, hepatitis), Fanconi anemia, idiopathic (autoimmune).","Radiação, drogas, vírus, Fanconi."],["lutdxlmkq","Treatment of aplastic anemia?","Withdraw offending agent, immunosuppression (antithymocyte globulin, cyclosporine), eltrombopag, bone marrow transplant.","Imunossupressão ou transplante de medula."],["ngl8kn109","What is Fanconi anemia?","Autosomal recessive DNA interstrand cross-link repair defect: bone marrow failure, short stature, café-au-lait spots, thumb/radial defects, increased malignancy (AML).","Falência medular e defeitos de polegar e rádio."],["3yt7zsyzq","What is hereditary spherocytosis?","Defect in RBC membrane proteins (ankyrin, spectrin, band 3) causing spherocytes and extravascular hemolysis.","Defeito de membrana; esferócitos."],["rabffaye3","Lab findings in hereditary spherocytosis?","Increased MCHC, increased RDW, positive EMA binding test (or osmotic fragility test), negative Coombs.","CHCM alto e teste EMA positivo."],["1mh8uc816","Complications of hereditary spherocytosis?","Splenomegaly, pigmented gallstones, aplastic crisis (parvovirus B19).","Esplenomegalia, cálculos e crise aplásica."],["pqw3vej0e","What is G6PD deficiency?","X-linked recessive deficiency causing decreased NADPH and glutathione, leading to oxidative hemolysis (Heinz bodies, bite cells).","Hemólise oxidativa; corpúsculos de Heinz."],["s1k1j0uk5","Triggers of hemolysis in G6PD deficiency?","Sulfa drugs, antimalarials (primaquine), dapsone, fava beans, infections, nitrofurantoin, rasburicase.","Sulfas, primaquina, favas, infecções."],["1plrkcsve","What is pyruvate kinase deficiency?","Autosomal recessive: decreased ATP, rigid RBCs, extravascular hemolysis, burr cells (echinocytes), neonatal hemolytic anemia.","Pouca ATP; hemólise extravascular."],["17zjvonva","What is paroxysmal nocturnal hemoglobinuria?","Acquired PIGA mutation causing absent GPI anchor for CD55/CD59 (complement inhibitors): complement-mediated intravascular hemolysis.","Falta CD55/CD59; hemólise por complemento."],["rv7rjv1f9","Clinical triad of paroxysmal nocturnal hemoglobinuria?","Coombs-negative hemolytic anemia, pancytopenia, venous thrombosis (e.g., Budd-Chiari).","Hemólise, pancitopenia e trombose."],["1fmi0w910","Diagnosis and treatment of PNH?","Flow cytometry showing absent CD55/CD59; eculizumab or ravulizumab (C5 inhibitors).","Citometria; eculizumabe."],["dle184ivy","What is the mutation in sickle cell disease?","Point mutation: glutamate replaced by valine at position 6 of beta-globin (HbS).","Ácido glutâmico trocado por valina."],["16l9rtx12","What triggers sickling?","Low O2, high altitude, acidosis, dehydration, infection.","Hipóxia, acidose, desidratação."],["1hqzm8j4g","Why are newborns with sickle cell disease initially asymptomatic?","High HbF levels protect for the first months.","HbF protege no início."],["h7o8pzlsw","What are complications of sickle cell disease?","Vaso-occlusive crises, autosplenectomy (Howell-Jolly bodies), encapsulated infections, Salmonella osteomyelitis, acute chest syndrome, aplastic crisis, avascular necrosis, stroke, priapism, renal papillary necrosis.","Crises de dor, autoesplenectomia, síndrome torácica."],["1fhu4fk1o","What is acute chest syndrome?","Vaso-occlusion in pulmonary microvasculature with fever, chest pain, infiltrates; most common cause of death in adults with sickle cell disease.","Principal causa de morte no adulto falciforme."],["6y7pcsn6b","What is dactylitis in sickle cell disease?","Painful swelling of hands and feet from vaso-occlusion in infants.","Inchaço doloroso de mãos e pés."],["2luf1tfl9","What is the most common cause of osteomyelitis in sickle cell disease?","Salmonella (although S. aureus is still common).","Salmonella."],["br86q013i","Which virus causes aplastic crisis in sickle cell disease?","Parvovirus B19.","Parvovírus B19."],["nc5g0rr3q","What is the renal manifestation of sickle cell trait?","Isosthenuria (inability to concentrate urine), hematuria, renal papillary necrosis; renal medullary carcinoma.","Urina não concentrada e necrose de papila."],["1dyxrhik8","Treatment of sickle cell disease?","Hydroxyurea (increases HbF), hydration, analgesia, transfusion, L-glutamine, crizanlizumab, bone marrow transplant, gene therapy.","Hidroxiureia aumenta HbF."],["2vk9n3bv4","What is HbC disease?","Glutamate replaced by lysine at position 6 of beta-globin: mild hemolysis, target cells, HbC crystals.","Troca por lisina; hemólise leve."],["ukdi4cgh3","What is HbSC disease?","Compound heterozygote: milder than HbSS; more retinopathy and avascular necrosis.","Mais leve que HbSS."],["1o4gpbtqz","What is autoimmune hemolytic anemia?","Hemolysis due to autoantibodies; positive direct Coombs test; spherocytes.","Hemólise por autoanticorpos; Coombs positivo."],["w3pre81q4","What is warm autoimmune hemolytic anemia?","IgG-mediated extravascular hemolysis; causes: SLE, CLL, drugs (methyldopa, penicillin), idiopathic.","IgG quente; LES, LLC, drogas."],["1ck86zh1f","What is cold autoimmune hemolytic anemia?","IgM and complement-mediated hemolysis with cold exposure (acrocyanosis); causes: Mycoplasma pneumoniae, EBV (infectious mononucleosis), CLL.","IgM no frio; Mycoplasma e EBV."],["ff8py71vu","Treatment of warm AIHA?","Glucocorticoids; rituximab; splenectomy if refractory.","Corticoide."],["1uxliwi1k","What is microangiopathic hemolytic anemia?","RBCs damaged passing through obstructed or narrowed vessels: schistocytes; seen in DIC, TTP/HUS, HELLP, SLE, malignant hypertension.","Hemácias fragmentadas em microvasos."],["1qg2y9m1g","What is macroangiopathic hemolytic anemia?","Mechanical destruction by prosthetic heart valves or aortic stenosis; schistocytes.","Hemólise por próteses valvares."],["9tuxtp1rl","Which infections cause hemolysis?","Malaria (Plasmodium), Babesia, Clostridium perfringens.","Malária e babesiose."],["2c9fbp1si","What is the RBC morphology in liver disease?","Target cells and acanthocytes (spur cells).","Células em alvo e acantócitos."],["1jew2mn1o","What is the RBC morphology in abetalipoproteinemia?","Acanthocytes.","Acantócitos."],["1m858wrnn","What are echinocytes (burr cells)?","RBCs with regular, small projections; seen in uremia, pyruvate kinase deficiency, artifact.","Projeções regulares; uremia."],["4qakvu1ft","What are dacrocytes (teardrop cells)?","Seen in myelofibrosis (marrow infiltration) and thalassemia.","Em lágrima; mielofibrose."],["1874lvem0","What are degmacytes (bite cells)?","RBCs after splenic removal of Heinz bodies; G6PD deficiency.","Células mordidas; G6PD."],["17exkqw1g","What are sickle cells?","Crescent-shaped RBCs in sickle cell disease.","Hemácias em foice."],["1hmttjh1l","What are spherocytes?","Small, round RBCs without central pallor; hereditary spherocytosis, warm AIHA.","Sem palidez central."],["j3e7p6fpu","What are macro-ovalocytes?","Large oval RBCs in megaloblastic anemia.","Hemácias grandes ovais."],["1lhtti15l","What are elliptocytes?","Oval RBCs in hereditary elliptocytosis (spectrin defect), usually asymptomatic.","Eliptocitose hereditária."],["19o96h8ag","What is rouleaux formation?","Stacks of RBCs from increased plasma proteins; multiple myeloma.","Hemácias empilhadas; mieloma."],["1hoxdwg1v","What lab finding distinguishes iron deficiency from anemia of chronic disease?","Ferritin (low in iron deficiency, normal/high in chronic disease) and TIBC (high vs low).","Ferritina e capacidade de ligação."],["do4k1q1go","What is the treatment of iron deficiency anemia?","Oral iron (ferrous sulfate); IV iron if intolerant or malabsorption; treat cause.","Ferro oral ou venoso; tratar a causa."],["wc4i2ih5z","What are side effects of oral iron?","Constipation, dark stools, GI upset.","Constipação e fezes escuras."],["1bt8c9412","What is iron overload's treatment?","Phlebotomy (hemochromatosis) or chelation (deferoxamine, deferasirox, deferiprone).","Flebotomia ou quelação."],["c20skvks1","What is anemia of CKD's mechanism?","Decreased erythropoietin production by the kidney.","Menos eritropoetina."],["4n8cs61x8","What is the pattern of anemia in hypothyroidism?","Usually normocytic or macrocytic.","Normo ou macrocítica."],["dgn2na1oy","What is polycythemia?","Increased hematocrit; can be relative (dehydration) or absolute (primary or secondary).","Hematócrito aumentado."],["15rtubgcw","What is secondary polycythemia?","Increased EPO from hypoxia (COPD, high altitude, smoking) or ectopic EPO (renal cell carcinoma, HCC, hemangioblastoma).","Eritropoetina alta por hipóxia ou tumor."],["g31zuv183","What is primary polycythemia (polycythemia vera)?","Myeloproliferative neoplasm with JAK2 V617F mutation; low EPO.","Neoplasia com JAK2; EPO baixa."],["wq0b1hwoo","Why do smokers have secondary polycythemia?","Carbon monoxide causes tissue hypoxia, increasing EPO.","Monóxido de carbono causa hipóxia."],["1y6rl69gg","What is the anemia associated with hookworm infection?","Iron deficiency anemia (Ancylostoma, Necator).","Ferropriva por ancilostomíase."],["92sxa6zfz","What is the anemia associated with Diphyllobothrium latum?","B12 deficiency (megaloblastic).","Falta de B12 pela tênia de peixe."],["1tm6tv7ay","What does hemoglobinuria with dark urine in the morning suggest?","Paroxysmal nocturnal hemoglobinuria.","Hemoglobinúria paroxística noturna."],["suq00u11k","What is March hemoglobinuria?","Intravascular hemolysis from repetitive foot trauma (long-distance running).","Hemólise por impacto repetido nos pés."],["8n5uzu1o4","What is aplastic crisis?","Transient arrest of erythropoiesis (parvovirus B19) in patients with chronic hemolysis, causing severe anemia with low reticulocytes.","Parada da produção com reticulócitos baixos."],["u1azt6ewy","What is splenic sequestration crisis?","Sudden pooling of blood in the spleen in children with sickle cell disease, causing hypovolemic shock.","Baço retém sangue; choque."],["14cfy7uw2","What is anemia's most common sign on exam?","Pallor (conjunctivae, palms).","Palidez."],["xh6pgc11b","What is high-output heart failure due to anemia?","Severe anemia increases cardiac output demands, causing heart failure.","Anemia grave sobrecarrega o coração."],["1sz6jno16","What is the cause of anemia in thalassemia trait vs iron deficiency in RBC count?","Thalassemia trait: normal or high RBC count; iron deficiency: low RBC count.","Talassemia: hemácias normais ou altas."],["18o682c1a","What is the HbA2 level in iron deficiency?","Normal or low (masking beta thalassemia trait if coexisting).","Normal ou baixa."],["1gbq49332","What is the treatment of beta thalassemia major?","Regular transfusions with iron chelation; hydroxyurea; luspatercept; stem cell transplant; gene therapy.","Transfusões e quelação de ferro."],["r6ru471pr","What is congenital dyserythropoietic anemia?","Inherited ineffective erythropoiesis with multinucleated erythroblasts.","Eritropoese ineficaz hereditária."],["g24l9u14h","What is transient erythroblastopenia of childhood?","Self-limited normocytic anemia from temporary red cell aplasia after viral illness in toddlers.","Aplasia eritroide transitória após virose."],["1k3skik1m","What anemia is associated with thymoma?","Pure red cell aplasia.","Aplasia eritroide pura."],["10r00s9pb","What anemia is associated with copper deficiency?","Microcytic or normocytic anemia with neutropenia (and myelopathy).","Anemia com neutropenia."],["5fqeyb17g","What is the anemia associated with zidovudine?","Macrocytic anemia.","Macrocítica."],["1jhyu35su","Which drugs cause megaloblastic anemia?","Methotrexate, trimethoprim, phenytoin, hydroxyurea, 5-FU, zidovudine.","Metotrexato, trimetoprima, fenitoína."],["14y3z1r18","Which drugs cause aplastic anemia?","Chloramphenicol, carbamazepine, felbamate, sulfonamides, methimazole/PTU, benzene.","Cloranfenicol, carbamazepina."],["1ik7t59n7","Which drugs cause immune hemolytic anemia?","Penicillins, cephalosporins, methyldopa, quinidine, NSAIDs.","Penicilinas e metildopa."],["1c5c5zg1d","What is a clue that anemia is due to marrow infiltration?","Leukoerythroblastic blood smear (nucleated RBCs, immature myeloid cells, teardrop cells).","Quadro leucoeritroblástico."],["osis4h6fb","What is the most common inherited hemolytic anemia in Northern Europeans?","Hereditary spherocytosis.","Esferocitose hereditária."],["1ghu5ycit","What is the most common enzyme deficiency causing hemolysis worldwide?","G6PD deficiency.","Deficiência de G6PD."],["andplbzwh","What hemoglobin electrophoresis finding characterizes sickle cell trait?","About 40% HbS and 60% HbA.","40% HbS e 60% HbA."],["rwdlst18j","Which RBC inclusion indicates oxidative stress?","Heinz bodies.","Corpúsculos de Heinz."],["qdfq7z5pt","What indicates intravascular hemolysis in the urine?","Hemoglobinuria and hemosiderinuria.","Hemoglobina e hemossiderina na urina."],["1nmem7a4p","What are the most common causes of death from cancer in the US?","Lung cancer is the leading cause for both sexes, followed by colorectal, pancreatic, and breast/prostate.","Pulmão é a principal causa."],["1suk6bu1l","What is the most common cancer in men and women (excluding skin)?","Men: prostate. Women: breast.","Próstata e mama."],["1a1r22z16","What is a hamartoma?","Disorganized overgrowth of tissues native to the site (e.g., lung hamartoma).","Crescimento desorganizado de tecido normal do local."],["82dsmo18c","What is a choristoma?","Normal tissue in an abnormal location (e.g., ectopic pancreatic tissue in stomach).","Tecido normal em lugar anormal."],["l8bxoxin0","What is metaplasia?","Reversible replacement of one differentiated cell type by another (e.g., Barrett esophagus).","Troca reversível de um tipo celular por outro."],["1mxdpuq1o","What is dysplasia?","Disordered, potentially precancerous cell growth; may be reversible.","Crescimento desordenado pré-maligno."],["16h5iwy3i","What is anaplasia?","Loss of structural and functional differentiation (poorly differentiated cells), a feature of malignancy.","Perda de diferenciação."],["hb8tlo3j8","What is desmoplasia?","Fibrous tissue formation in response to neoplasm (e.g., linitis plastica).","Fibrose reativa ao tumor."],["1ugycbl2u","What is carcinoma in situ?","Neoplastic cells with intact basement membrane; no invasion.","Neoplasia sem invadir a membrana basal."],["uz7hgxvc8","What are psammoma bodies?","Laminated concentric calcifications seen in papillary thyroid carcinoma, serous ovarian carcinoma, meningioma, mesothelioma.","Calcificações concêntricas."]]},{"name":"Pathology (Part 2)","cards":[["4cg1f51x5","What is hemophilia A?","X-linked recessive factor VIII deficiency: hemarthroses, easy bruising, increased PTT, normal PT and bleeding time.","Falta de fator VIII; TTPa alto."],["4cg1ci1x5","What is hemophilia B?","X-linked recessive factor IX deficiency (Christmas disease); same presentation as hemophilia A.","Falta de fator IX."],["4cg1df1x5","What is hemophilia C?","Autosomal recessive factor XI deficiency; mild bleeding, increased PTT.","Falta de fator XI."],["aw3cq49e9","Treatment of hemophilia A?","Factor VIII concentrate, desmopressin (mild cases), emicizumab (bispecific antibody mimicking factor VIII).","Fator VIII, desmopressina, emicizumabe."],["7wb6mfuvu","What is vitamin K deficiency's lab pattern?","Increased PT and PTT, normal bleeding time and platelets.","TP e TTPa altos."],["1h7bn3l10","What is von Willebrand disease?","Most common inherited bleeding disorder, usually autosomal dominant: mucosal bleeding, increased bleeding time, normal or increased PTT, normal PT.","Doença hereditária de sangramento mais comum."],["13pcvvo15","Why may PTT be prolonged in von Willebrand disease?","vWF stabilizes factor VIII; low vWF decreases factor VIII.","vWF baixo reduz o fator VIII."],["13o9pr884","Diagnosis and treatment of von Willebrand disease?","Ristocetin cofactor assay (decreased agglutination); desmopressin (releases vWF), vWF concentrates.","Teste da ristocetina; desmopressina."],["13t9x5u1h","What is immune thrombocytopenia (ITP)?","Anti-GpIIb/IIIa IgG antibodies cause splenic destruction of platelets; increased megakaryocytes in marrow.","Anticorpos destroem plaquetas no baço."],["nignffcd1","How does ITP present in children vs adults?","Children: acute, self-limited after viral infection. Adults: chronic, often in women, may be associated with SLE, HIV, HCV.","Criança aguda pós-viral; adulto crônica."],["1p2ro8qy9","Treatment of ITP?","Glucocorticoids, IVIG, rituximab, thrombopoietin receptor agonists, splenectomy.","Corticoide e imunoglobulina."],["ecxwk4iy4","What is thrombotic thrombocytopenic purpura (TTP)?","Inhibition or deficiency of ADAMTS13 (vWF-cleaving protease) leading to large vWF multimers, platelet microthrombi, MAHA.","Falta de ADAMTS13; microtrombos."],["dumc0bsfb","Clinical features of TTP?","Thrombocytopenia, MAHA (schistocytes), fever, neurologic symptoms, renal dysfunction (pentad, often incomplete).","Plaquetopenia, hemólise, sintomas neurológicos."],["1p38nrby9","Treatment of TTP?","Plasma exchange, glucocorticoids, rituximab, caplacizumab; avoid platelet transfusion.","Plasmaférese."],["11i1btqgd","What is hemolytic uremic syndrome?","Thrombocytopenia, MAHA, and acute kidney injury, typically after EHEC O157:H7 (Shiga-like toxin) in children.","Plaquetopenia, hemólise e lesão renal após E. coli."],["11kryx01u","What is DIC?","Widespread activation of clotting with consumption of platelets and factors: bleeding and thrombosis.","Coagulação disseminada com consumo."],["qgf51r1kc","Causes of DIC?","Sepsis (gram-negative), trauma, obstetric complications (abruption, amniotic fluid embolism), acute pancreatitis, malignancy (APL), nephrotic syndrome, transfusion reaction, snakebite.","Sepse, trauma, obstetrícia, LPA."],["10c77fufw","Lab findings in DIC?","Low platelets, increased PT, PTT, increased D-dimer, decreased fibrinogen, schistocytes.","Plaquetas e fibrinogênio baixos; TP, TTPa e D-dímero altos."],["9qwlglbhn","What is Bernard-Soulier syndrome?","Autosomal recessive GpIb deficiency: defective platelet adhesion, large platelets, thrombocytopenia, no agglutination with ristocetin (not corrected by normal plasma).","Falta de GpIb; plaquetas grandes."],["1rqhcaj14","What is Glanzmann thrombasthenia?","Autosomal recessive GpIIb/IIIa deficiency: defective platelet aggregation; normal platelet count; no clumping on smear.","Falta de GpIIb/IIIa; não agregam."],["li1cmq1on","What is uremic platelet dysfunction?","Uremic toxins impair platelet adhesion and aggregation: increased bleeding time; treated with desmopressin or dialysis.","Uremia prejudica plaquetas."],["a8py4eqqj","What is factor V Leiden?","Most common inherited thrombophilia (Whites): mutant factor V resistant to activated protein C.","Trombofilia hereditária mais comum."],["151r6y9q0","What is the prothrombin G20210A mutation?","Point mutation in the 3' UTR increasing prothrombin production and venous thrombosis risk.","Mais protrombina e trombose."],["ed0ae8iyj","What is antithrombin deficiency's clinical clue?","Heparin resistance (little PTT rise with heparin); thrombosis; also acquired in nephrotic syndrome.","Resistência à heparina."],["1p0qqs3mb","What is protein C or S deficiency's classic complication?","Warfarin-induced skin necrosis due to early transient hypercoagulability.","Necrose de pele pela varfarina."],["1icbghy1p","What is antiphospholipid syndrome?","Autoantibodies (lupus anticoagulant, anticardiolipin, anti-beta2 glycoprotein I) with arterial or venous thrombosis or pregnancy loss; prolonged PTT not corrected by mixing.","Tromboses e abortos por anticorpos antifosfolípides."],["dnshx71ou","Treatment of antiphospholipid syndrome?","Warfarin (DOACs avoided in high-risk); heparin and aspirin in pregnancy.","Varfarina; heparina na gestação."],["1vf05ro15","What is the classic presentation of acute lymphoblastic leukemia?","Children (peak 2-5 years): bone pain, fever, fatigue, bleeding, hepatosplenomegaly, lymphadenopathy; >20% lymphoblasts.","Criança com dor óssea, febre e sangramento."],["od7618bhs","Markers of B-ALL?","TdT+, CD10+, CD19+, CD20+.","TdT, CD10, CD19."],["1i6fkh31n","Markers and presentation of T-ALL?","TdT+, CD1a, CD2-CD8; adolescent male with mediastinal mass (SVC syndrome).","Adolescente com massa mediastinal."],["13efs9d1c","Which genetic findings affect prognosis in ALL?","t(12;21) good prognosis (children); t(9;22) Philadelphia chromosome poor prognosis (adults).","t(12;21) bom; Filadélfia ruim."],["25yx991xd","Which sanctuary sites can ALL relapse in?","CNS and testes (require prophylaxis).","SNC e testículos."],["1sireecac","What is acute myeloid leukemia?","Neoplastic proliferation of myeloblasts (>20%); median age ~65; Auer rods; MPO positive.","Mieloblastos com bastões de Auer."],["49xqf41ms","What is acute promyelocytic leukemia?","AML subtype with t(15;17) PML-RARA fusion; Auer rods; high risk of DIC; treated with all-trans retinoic acid and arsenic trioxide.","t(15;17); risco de CIVD; ATRA."],["1j7t5he1k","What is AML M7 associated with?","Acute megakaryoblastic leukemia; Down syndrome.","Leucemia megacarioblástica; Down."],["1tks9c4kj","What is chronic lymphocytic leukemia?","Most common leukemia in adults (>60): CD5+ CD20+ B cells, smudge cells; often asymptomatic, lymphadenopathy; warm AIHA.","Leucemia mais comum do idoso; células borradas."],["1ao325k1w","What is Richter transformation?","CLL transforming into aggressive diffuse large B-cell lymphoma.","LLC vira linfoma agressivo."],["1vdcquo11","What is hairy cell leukemia?","Mature B-cell tumor in older men with hairy cytoplasmic projections; TRAP positive (and CD11c, CD103, annexin A1); BRAF V600E; dry marrow tap, splenomegaly.","Células pilosas; TRAP; baço grande."],["10qyqa5mp","Treatment of hairy cell leukemia?","Purine analogs (cladribine, pentostatin).","Cladribina."],["4ndhao12t","What is chronic myeloid leukemia?","Myeloproliferative neoplasm with t(9;22) BCR-ABL fusion (Philadelphia chromosome): increased neutrophils, metamyelocytes, basophils, splenomegaly.","Cromossomo Filadélfia; BCR-ABL."],["1eopk711e","How is CML distinguished from a leukemoid reaction?","CML: low leukocyte alkaline phosphatase, basophilia, BCR-ABL. Leukemoid: high LAP, Döhle bodies, toxic granulation.","LMC tem fosfatase alcalina baixa."],["1p2vth1y9","Treatment of CML?","Tyrosine kinase inhibitors (imatinib, dasatinib, nilotinib).","Imatinibe."],["1v24fpy1k","What is blast crisis in CML?","Progression to acute leukemia (AML or ALL).","Evolução para leucemia aguda."],["c19jvq18g","What is polycythemia vera?","JAK2 V617F myeloproliferative neoplasm: increased RBCs (and often WBCs and platelets), low EPO, pruritus after hot shower, erythromelalgia, Budd-Chiari risk.","JAK2; coceira após banho quente."],["191rb171y","Treatment of polycythemia vera?","Phlebotomy, aspirin, hydroxyurea, ruxolitinib.","Flebotomia e hidroxiureia."],["17bg9ar1r","What is essential thrombocythemia?","Myeloproliferative neoplasm with platelet overproduction (JAK2, CALR, MPL mutations): bleeding and thrombosis.","Excesso de plaquetas."],["1wpvgfh19","What is primary myelofibrosis?","Atypical megakaryocytes release fibrogenic factors causing marrow fibrosis: massive splenomegaly, teardrop cells, dry tap, extramedullary hematopoiesis.","Fibrose medular, baço enorme, dacriócitos."],["1rkekrlqe","What is Hodgkin lymphoma?","Lymphoma with Reed-Sternberg cells (CD15+, CD30+ binucleate owl eye), contiguous lymph node spread, bimodal age distribution, mediastinal involvement, B symptoms.","Células de Reed-Sternberg."],["1kog9os1q","Most common subtype of Hodgkin lymphoma?","Nodular sclerosis (young women, mediastinal mass).","Esclerose nodular."],["qpgnys1nk","Which Hodgkin subtype has the best and worst prognosis?","Best: lymphocyte-rich; worst: lymphocyte-depleted (elderly, HIV).","Rica em linfócitos é a melhor."],["n33d2u1y6","What are B symptoms?","Fever, night sweats, weight loss (>10% in 6 months).","Febre, sudorese noturna e emagrecimento."],["ioh2a01db","What infection is associated with Hodgkin lymphoma?","EBV (especially mixed cellularity).","Vírus Epstein-Barr."],["18ykzea1l","What is the most common non-Hodgkin lymphoma?","Diffuse large B-cell lymphoma (older adults, aggressive, often extranodal).","Linfoma difuso de grandes células B."],["1hmrjcwob","What is follicular lymphoma?","Indolent B-cell lymphoma with t(14;18) causing BCL-2 overexpression (anti-apoptotic); painless waxing and waning lymphadenopathy.","t(14;18); BCL-2; linfonodos que variam."],["1r7ztu81b","What is mantle cell lymphoma?","Aggressive B-cell lymphoma with t(11;14) causing cyclin D1 overexpression; CD5+; older men.","t(11;14); ciclina D1; CD5+."],["f5yfgu1ru","What is Burkitt lymphoma?","t(8;14) c-MYC overexpression; starry sky appearance; endemic (African) jaw lesion, sporadic (abdominal, ileocecal); EBV associated.","t(8;14); céu estrelado; mandíbula."],["1ggrbqcuk","What is marginal zone lymphoma?","Indolent B-cell lymphoma associated with chronic inflammation (Hashimoto, Sjögren, H. pylori: MALT lymphoma).","Linfoma MALT ligado à inflamação crônica."],["1d9fnqzec","What is primary CNS lymphoma?","EBV-associated DLBCL in immunocompromised (HIV); ring-enhancing lesion.","Linfoma cerebral em HIV."],["olwyti1xg","What is adult T-cell leukemia/lymphoma?","Caused by HTLV-1 (Japan, West Africa, Caribbean): cutaneous lesions, lytic bone lesions, hypercalcemia.","HTLV-1; hipercalcemia e lesões ósseas."],["gd0u511as","What is mycosis fungoides?","Cutaneous T-cell lymphoma (CD4+) with skin patches and plaques, Pautrier microabscesses; Sézary syndrome when it spreads to blood (cerebriform cells).","Linfoma T de pele; Sézary."],["1irrcasnu","What is multiple myeloma?","Monoclonal plasma cell neoplasm: lytic bone lesions, hypercalcemia, renal insufficiency, anemia (CRAB), M spike, Bence Jones proteinuria.","Mieloma: cálcio alto, rim, anemia, ossos."],["lf4bcs19b","What does a monoclonal M spike indicate?","Overproduction of a single immunoglobulin (most often IgG) in multiple myeloma or MGUS.","Imunoglobulina monoclonal."],["1u4fi3e1v","Why does multiple myeloma cause renal failure?","Light chain cast nephropathy (myeloma kidney), hypercalcemia, amyloidosis.","Cadeias leves lesam o rim."],["noz4cd1qb","Which infections are common in multiple myeloma?","Encapsulated bacteria (low normal immunoglobulins).","Bactérias encapsuladas."],["wqb1ty1v5","What is MGUS?","Monoclonal gammopathy of undetermined significance: M protein without CRAB features; about 1% per year progress to myeloma.","Pico monoclonal sem dano; 1% ao ano evolui."],["1pyospn1k","What is Waldenström macroglobulinemia?","Lymphoplasmacytic lymphoma with IgM M spike: hyperviscosity (blurred vision, Raynaud), no lytic bone lesions.","IgM e hiperviscosidade."],["1l8f98ao0","What is AL amyloidosis?","Deposition of immunoglobulin light chains (associated with plasma cell dyscrasias): nephrotic syndrome, cardiomyopathy, macroglossia, neuropathy.","Depósito de cadeias leves."],["1svh0oz1t","What is Langerhans cell histiocytosis?","Proliferation of Langerhans cells (CD1a+, S-100+, Birbeck granules - tennis racket): lytic bone lesions, skin rash, diabetes insipidus in children.","Grânulos de Birbeck; lesões ósseas."],["1q7c7071r","What is hemophagocytic lymphohistiocytosis?","Systemic overactivation of macrophages and CTLs: fever, pancytopenia, hepatosplenomegaly, very high ferritin; often EBV triggered.","Ferritina altíssima e pancitopenia."],["hks52r40i","What is myelodysplastic syndrome?","Clonal stem cell disorder with ineffective hematopoiesis and dysplasia (pseudo-Pelger-Huët neutrophils, ringed sideroblasts); risk of AML.","Medula displásica; risco de LMA."],["1mol22pok","What is a pseudo-Pelger-Huët anomaly?","Bilobed neutrophils (spectacles), seen in myelodysplastic syndromes.","Neutrófilos bilobados; mielodisplasia."],["3keulo1ro","What are acute hemolytic transfusion reactions?","ABO incompatibility (type II hypersensitivity): fever, hypotension, flank pain, hemoglobinuria, DIC; within 1 hour.","Incompatibilidade ABO; dor lombar e hemoglobinúria."],["853fmx1wk","What is febrile nonhemolytic transfusion reaction?","Cytokines from donor WBCs cause fever and chills; prevented by leukoreduction.","Febre por citocinas; leucorredução."],["a7tdlxm0l","What is an allergic transfusion reaction?","Recipient IgE against donor plasma proteins: urticaria and pruritus; severe anaphylaxis in IgA deficiency.","Urticária; anafilaxia na deficiência de IgA."],["1wigpm01y","What is TRALI?","Transfusion-related acute lung injury: donor antibodies activate neutrophils in recipient lungs; respiratory distress within 6 hours, noncardiogenic pulmonary edema.","Lesão pulmonar aguda após transfusão."],["w79b2r1up","What is TACO?","Transfusion-associated circulatory overload: volume overload, hypertension, pulmonary edema; elevated BNP.","Sobrecarga de volume."],["2ea9oh1ys","What is delayed hemolytic transfusion reaction?","Anamnestic antibody response to RBC antigens days to weeks after transfusion; mild extravascular hemolysis.","Hemólise tardia por anticorpos."],["8f4d71u7e","What is transfusion-associated graft-versus-host disease?","Donor T cells attack an immunocompromised recipient; prevented by irradiating blood products.","Linfócitos do doador atacam; irradiar."],["10v2bsb59","What is the tumor lysis syndrome?","Massive tumor cell death after chemotherapy (lymphomas, leukemias): hyperkalemia, hyperphosphatemia, hypocalcemia, hyperuricemia, AKI.","Potássio, fosfato e ácido úrico altos; cálcio baixo."],["1tsgcqv4k","How is tumor lysis syndrome prevented?","Aggressive hydration, allopurinol or rasburicase.","Hidratação e alopurinol ou rasburicase."],["1elqlwd1e","What is leukostasis?","Very high blast count (AML) causing hyperviscosity: respiratory distress, neurologic symptoms; emergency leukapheresis.","Hiperleucocitose obstrui vasos."],["176fyw93b","What is heparin-induced thrombocytopenia?","IgG against PF4-heparin complexes activating platelets: thrombocytopenia (5-10 days after heparin) and thrombosis.","Anticorpo anti-PF4; trombose com plaquetopenia."],["ckwec937h","What are causes of neutropenia?","Chemotherapy, aplastic anemia, viral infections, drugs (clozapine, carbamazepine, methimazole), autoimmune, sepsis.","Quimioterapia, drogas, infecções."],["1q6yc5l1y","What is the treatment of febrile neutropenia?","Empiric broad-spectrum IV antibiotics (antipseudomonal, e.g., cefepime).","Antibiótico antipseudomonas imediato."],["slaj0k1ov","What is lymphopenia associated with?","HIV, DiGeorge, SCID, steroids, radiation, SLE, sepsis.","HIV, corticoide, imunodeficiências."],["11b6imir3","What is the most common cause of eosinophilia worldwide?","Parasitic infections (helminths).","Parasitoses."],["cn36la1f2","What is the most common cause of eosinophilia in developed countries?","Allergic disorders (asthma, allergies) and drugs.","Alergias e medicamentos."],["1mv3hl21k","What is mastocytosis?","Clonal mast cell proliferation (KIT D816V): urticaria pigmentosa (Darier sign), flushing, peptic ulcers, elevated tryptase.","Excesso de mastócitos; sinal de Darier."],["g62yzofca","What does a positive Darier sign indicate?","Urtication of a skin lesion when rubbed (mast cell degranulation), as in urticaria pigmentosa.","Lesão vira urticária ao esfregar."],["1er3ei46p","What is the WHO threshold of blasts for acute leukemia?","At least 20% blasts in marrow or blood.","20% de blastos."],["xv1ce2nd7","What is the characteristic CBC in acute leukemia?","Anemia, thrombocytopenia, variable WBC with circulating blasts.","Anemia, plaquetopenia e blastos."],["1trkdpf19","What is the role of TdT in diagnosing leukemia?","Marker of lymphoblasts (ALL), absent in myeloid blasts and mature lymphocytes.","Marca linfoblastos."],["1c6knzz1w","What is the role of myeloperoxidase in diagnosing leukemia?","Positive in myeloblasts (AML).","Positiva na LMA."],["k18sfg1pk","What is a chloroma (myeloid sarcoma)?","Extramedullary tumor of myeloblasts, associated with AML.","Tumor extramedular de mieloblastos."],["ip1kaefai","What is the typical presentation of CLL on blood smear?","Many small mature lymphocytes and smudge cells.","Linfócitos maduros e células borradas."],["5ue5aigbe","Which leukemia is associated with hypogammaglobulinemia and infections?","CLL.","LLC."],["z3u6m9fzs","Which lymphoma is associated with celiac disease?","Enteropathy-associated T-cell lymphoma.","Linfoma T associado à enteropatia."],["1g985qnwk","Which lymphoma is associated with breast implants?","Breast implant-associated anaplastic large cell lymphoma (ALCL).","Linfoma anaplásico de grandes células."],["1hhg8wq1e","Which lymphoma has t(2;5) and ALK?","Anaplastic large cell lymphoma (children/young adults).","Linfoma anaplásico ALK+."],["1jbiullpw","Which hematologic malignancy is associated with HIV and HHV-8 body cavity effusions?","Primary effusion lymphoma.","Linfoma de efusão primária."],["o85ux41wt","Which lymphoma is associated with Sjögren syndrome?","Marginal zone (MALT) lymphoma.","Linfoma MALT."],["5pb1rf12o","What is a 'starry sky' appearance?","Sheets of lymphocytes with interspersed tingible body macrophages, characteristic of Burkitt lymphoma.","Burkitt."],["qg8sww1dn","What lab finding is characteristic of hyperviscosity syndrome?","Very high serum protein (IgM) causing visual changes and neurologic symptoms; treated with plasmapheresis.","Proteína muito alta; plasmaférese."],["shmwk2lzx","What is the Philadelphia chromosome?","t(9;22) BCR-ABL fusion: CML and some ALL.","Translocação 9;22."],["1uomohh1j","Which translocation is associated with APL?","t(15;17).","t(15;17)."],["uewnn0921","Which translocation is associated with Burkitt lymphoma?","t(8;14) c-MYC.","t(8;14)."],["1o1sdiam3","Which translocation is associated with follicular lymphoma?","t(14;18) BCL-2.","t(14;18)."],["jav65u8jl","Which translocation is associated with mantle cell lymphoma?","t(11;14) cyclin D1.","t(11;14)."],["c6f1ghboh","What is the cause of secondary (therapy-related) AML?","Alkylating agents and topoisomerase II inhibitors.","Agentes alquilantes e inibidores da topoisomerase II."],["asr67u1ss","What is the cause of thrombocytosis in iron deficiency?","Reactive thrombocytosis from iron deficiency (and inflammation, splenectomy).","Plaquetose reativa."],["nb4gij11n","What is the prognosis of untreated APL vs treated?","Untreated is rapidly fatal from DIC; with ATRA and arsenic, cure rates are very high.","Com ATRA e arsênico a cura é alta."],["7ztkyx8jl","What is the 'Auer rod'?","Peroxidase-positive cytoplasmic inclusions in myeloblasts; numerous in APL.","Inclusões em bastão nos mieloblastos."],["1aquz8hfb","What are the hallmarks of cancer?","Growth signal self-sufficiency, evasion of growth suppressors and apoptosis, limitless replication, sustained angiogenesis, invasion and metastasis, deregulated metabolism, immune evasion.","Características fundamentais do câncer."],["1ecawf9jx","What is the difference between tumor grade and stage?","Grade: degree of differentiation (histology). Stage: extent of spread (TNM); stage has more prognostic value.","Grau é diferenciação; estádio é extensão."],["db578r18w","What does the TNM system describe?","Tumor size/invasion, lymph Node involvement, distant Metastasis.","Tumor, linfonodos e metástase."],["aj0dbychg","Which carcinomas spread via lymphatics and which sarcomas spread hematogenously?","Carcinomas usually spread via lymphatics; sarcomas hematogenously (exceptions: follicular thyroid, choriocarcinoma, RCC, HCC spread hematogenously).","Carcinoma por linfa; sarcoma pelo sangue."],["1nhzk776j","Which oncogene is associated with neuroblastoma?","MYCN (N-myc) amplification.","Amplificação de MYCN."],["ox0hz11tm","Which oncogene is associated with colon, lung, and pancreatic cancer?","KRAS.","KRAS."],["1u81jym1w","What is the function of the tumor suppressor APC?","Regulates beta-catenin (Wnt pathway); loss causes colorectal cancer (FAP).","Controla a beta-catenina."],["1cjm2je1k","Which tumor markers are associated with germ cell tumors?","AFP (yolk sac tumor), beta-hCG (choriocarcinoma), LDH.","AFP, beta-hCG e LDH."],["rjgvgo139","Which tumor marker is associated with ovarian cancer?","CA-125.","CA-125."],["1ml6unf1u","Which paraneoplastic syndrome is associated with small cell lung cancer and causes proximal muscle weakness that improves with use?","Lambert-Eaton myasthenic syndrome (antibodies against presynaptic Ca2+ channels).","Síndrome de Lambert-Eaton."],["1ay29q01m","Which carcinogen is associated with bladder cancer?","Aromatic amines (aniline dyes), smoking, cyclophosphamide, Schistosoma haematobium (squamous).","Tabaco, anilinas, ciclofosfamida."]]},{"name":"Pharmacology","cards":[["fe5in523v","In which cell cycle phase do antimetabolites act?","S phase.","Fase S."],["12gjfcm1s","In which cell cycle phase do microtubule inhibitors act?","M phase (vinca alkaloids, taxanes).","Fase M."],["1ygr45iyb","In which cell cycle phase does bleomycin act?","G2 phase.","Fase G2."],["am5syj1bp","Which chemotherapy classes are cell cycle-independent?","Alkylating agents, platinum compounds, anthracyclines (most), nitrosoureas.","Alquilantes, platinas, antraciclinas."],["698k6w9sz","Mechanism of methotrexate?","Folic acid analog that competitively inhibits dihydrofolate reductase, decreasing dTMP and DNA synthesis.","Inibe a di-hidrofolato redutase."],["1n3fl031i","Uses of methotrexate?","Cancers (leukemias, lymphomas, choriocarcinoma, sarcomas), ectopic pregnancy, medical abortion, rheumatoid arthritis, psoriasis, IBD, vasculitis.","Câncer, gravidez ectópica, artrite reumatoide."],["1anmeb91b","Adverse effects of methotrexate?","Myelosuppression (reversible with leucovorin), hepatotoxicity, mucositis, pulmonary fibrosis, folate deficiency, nephrotoxicity, teratogenicity.","Mielossupressão, fígado, mucosite; leucovorina resgata."],["1jlh58d17","Mechanism of 5-fluorouracil?","Pyrimidine analog converted to 5-FdUMP, which forms a complex with folic acid and inhibits thymidylate synthase.","Inibe a timidilato sintase."],["5ghzyt1ty","Uses and adverse effects of 5-FU?","Colon, pancreatic, and other GI cancers; topical for basal cell carcinoma and actinic keratosis. Myelosuppression, palmar-plantar erythrodysesthesia (hand-foot syndrome); toxicity not reversed by leucovorin (enhanced).","Câncer de cólon; síndrome mão-pé."],["39wvgigxt","What is capecitabine?","Oral prodrug of 5-FU.","Pró-droga oral do 5-FU."],["xhvu50kh5","Mechanism of cytarabine?","Pyrimidine analog that inhibits DNA polymerase.","Inibe a DNA polimerase."],["1qz5j3614","Uses and adverse effects of cytarabine?","Leukemias (AML), lymphomas; myelosuppression with megaloblastic anemia.","LMA; mielossupressão."],["d4a6ygtbp","Mechanism of gemcitabine?","Pyrimidine analog that inhibits ribonucleotide reductase and DNA polymerase.","Inibe a ribonucleotídeo redutase."],["177u35111","Mechanism and uses of azathioprine and 6-mercaptopurine?","Purine analogs that decrease de novo purine synthesis (activated by HGPRT); leukemias, IBD, autoimmune diseases, transplant.","Análogos de purina; leucemia e imunossupressão."],["r1btjw1qu","Why should allopurinol be used cautiously with azathioprine?","Xanthine oxidase metabolizes 6-MP; allopurinol increases toxicity (reduce dose).","Alopurinol aumenta a toxicidade."],["4peasx7rl","Mechanism and use of cladribine?","Purine analog resistant to adenosine deaminase; hairy cell leukemia.","Análogo de purina; tricoleucemia."],["v0celmdlx","Mechanism and use of hydroxyurea?","Inhibits ribonucleotide reductase, decreasing DNA synthesis; sickle cell disease (increases HbF), myeloproliferative disorders, melanoma.","Inibe ribonucleotídeo redutase; aumenta HbF."],["1mxlkjupr","Mechanism of cyclophosphamide?","Alkylating agent that cross-links DNA at guanine N-7; requires hepatic activation (CYP450).","Alquilante; precisa ativação hepática."],["u4dj2f1q1","Adverse effects of cyclophosphamide?","Myelosuppression, hemorrhagic cystitis and bladder cancer (prevent with mesna and hydration), SIADH, infertility.","Cistite hemorrágica; prevenir com mesna."],["jxcxto1qh","Mechanism and use of nitrosoureas (carmustine, lomustine)?","Alkylating agents that cross the blood-brain barrier; brain tumors (glioblastoma).","Atravessam a barreira; tumores cerebrais."],["l1ox8n1ud","Adverse effects of nitrosoureas?","CNS toxicity (convulsions, dizziness, ataxia), pulmonary fibrosis.","Toxicidade no SNC e fibrose pulmonar."],["75bvbo18s","Mechanism and use of busulfan?","Alkylating agent; used to ablate bone marrow before stem cell transplant; adverse: pulmonary fibrosis, hyperpigmentation.","Ablação medular; fibrose pulmonar."],["1guue508l","Mechanism of platinum compounds (cisplatin, carboplatin, oxaliplatin)?","Cross-link DNA.","Ligações cruzadas no DNA."],["dmd1be1t7","Adverse effects of cisplatin and carboplatin?","Nephrotoxicity (prevent with amifostine and chloride diuresis), peripheral neuropathy, ototoxicity.","Nefro e ototoxicidade, neuropatia."],["jau51n1aj","Adverse effect of oxaliplatin?","Peripheral neuropathy (cold-induced).","Neuropatia piora com frio."],["1x5yb70rj","Mechanism of anthracyclines (doxorubicin, daunorubicin)?","Generate free radicals, intercalate in DNA, inhibit topoisomerase II.","Radicais livres e inibição da topoisomerase II."],["1ig1arl17","Adverse effects of anthracyclines?","Dilated cardiomyopathy (prevent with dexrazoxane), myelosuppression, alopecia.","Cardiomiopatia dilatada."],["uek2pgn6s","Mechanism and use of bleomycin?","Induces free radical formation causing DNA strand breaks; testicular cancer, Hodgkin lymphoma.","Radicais livres; câncer de testículo e Hodgkin."],["1k3f8tt12","Adverse effects of bleomycin?","Pulmonary fibrosis, skin hyperpigmentation.","Fibrose pulmonar."],["1qcf06i1q","Mechanism and use of dactinomycin?","Intercalates in DNA, preventing RNA synthesis; Wilms tumor, Ewing sarcoma, rhabdomyosarcoma (childhood tumors).","Intercala no DNA; tumores infantis."],["z4ktrv1n0","Mechanism of vinca alkaloids (vincristine, vinblastine)?","Bind beta-tubulin and inhibit microtubule polymerization (M phase).","Impedem a formação de microtúbulos."],["y63fvb1wi","Adverse effects of vincristine vs vinblastine?","Vincristine: neurotoxicity (areflexia, peripheral neuritis), constipation (paralytic ileus). Vinblastine: myelosuppression (vinBLASTine BLASTs bone marrow).","Vincristina: neuropatia; vimblastina: medula."],["15lwr2jld","Mechanism of taxanes (paclitaxel, docetaxel)?","Hyperstabilize polymerized microtubules, preventing breakdown in M phase.","Estabilizam microtúbulos."],["edngkx1sz","Adverse effects of taxanes?","Myelosuppression, neuropathy, hypersensitivity.","Mielossupressão e neuropatia."],["zndkus1oh","Mechanism of irinotecan and topotecan?","Inhibit topoisomerase I, preventing DNA unwinding and replication.","Inibem a topoisomerase I."],["1v2e3kbx5","Adverse effects of irinotecan?","Severe diarrhea, myelosuppression.","Diarreia grave."],["14mdv8r1m","Mechanism of etoposide and teniposide?","Inhibit topoisomerase II, increasing DNA degradation.","Inibem a topoisomerase II."],["ts8peh1jp","Uses of etoposide?","Testicular cancer, small cell lung cancer, leukemias, lymphomas.","Testículo e pulmão de pequenas células."],["198123v1v","Mechanism and use of tamoxifen?","Selective estrogen receptor modulator: antagonist in breast, agonist in bone and endometrium; ER+ breast cancer treatment and prevention.","Antagonista na mama, agonista no útero."],["2alfou1xz","Adverse effects of tamoxifen?","Endometrial cancer, venous thromboembolism, hot flashes.","Câncer de endométrio e trombose."],["1dl8iuh1n","Mechanism and use of raloxifene?","SERM: agonist in bone, antagonist in breast and uterus; osteoporosis and breast cancer prevention; risk of thromboembolism.","Agonista no osso; não estimula o endométrio."],["101zqskeg","Mechanism of aromatase inhibitors (anastrozole, letrozole, exemestane)?","Inhibit peripheral conversion of androgens to estrogen; ER+ breast cancer in postmenopausal women.","Bloqueiam a aromatase."],["109atmaj4","Adverse effect of aromatase inhibitors?","Osteoporosis, arthralgias.","Osteoporose."],["2z2gus116","Mechanism and use of trastuzumab?","Monoclonal antibody against HER2 (tyrosine kinase receptor); HER2+ breast and gastric cancer.","Anti-HER2."],["gvtajm11p","Adverse effect of trastuzumab?","Cardiotoxicity (reversible decreased EF).","Cardiotoxicidade reversível."],["3bcn0d1c4","Mechanism and use of imatinib?","BCR-ABL tyrosine kinase inhibitor (also c-KIT); CML and GIST.","Inibe BCR-ABL e c-KIT."],["1rwnvtx59","Mechanism and use of rituximab?","Monoclonal antibody against CD20 (B cells); B-cell lymphomas, CLL, ITP, rheumatoid arthritis, pemphigus.","Anti-CD20."],["hoi1qr1oq","Adverse effect of rituximab?","Infusion reactions, progressive multifocal leukoencephalopathy (JC virus), HBV reactivation.","LEMP e reativação do HBV."],["gl5krf8rv","Mechanism and use of bevacizumab?","Monoclonal antibody against VEGF, inhibiting angiogenesis; colorectal cancer, renal cell carcinoma, NSCLC, macular degeneration.","Anti-VEGF."],["1we1ise1u","Adverse effects of bevacizumab?","Hemorrhage, blood clots, impaired wound healing, GI perforation, hypertension, proteinuria.","Sangramento, cicatrização ruim, perfuração."],["1t1dlf6tr","Mechanism and use of cetuximab and panitumumab?","Monoclonal antibodies against EGFR; KRAS wild-type colorectal cancer, head and neck cancer.","Anti-EGFR."],["108we8n1e","Adverse effect of EGFR inhibitors?","Acneiform rash, hypomagnesemia, diarrhea.","Erupção acneiforme."],["wsn09ausz","Mechanism and use of erlotinib, gefitinib, osimertinib?","EGFR tyrosine kinase inhibitors; NSCLC with EGFR mutations.","Inibidores de EGFR; câncer de pulmão."],["17jo5zb3n","Mechanism and use of vemurafenib and dabrafenib?","BRAF V600E kinase inhibitors; metastatic melanoma (often with MEK inhibitors).","Inibidores de BRAF; melanoma."],["1s5z15i7q","Mechanism and use of bortezomib and carfilzomib?","Proteasome inhibitors inducing arrest and apoptosis; multiple myeloma, mantle cell lymphoma.","Inibidores do proteassoma; mieloma."],["1tslpgr1k","Adverse effect of bortezomib?","Peripheral neuropathy, herpes zoster reactivation (give acyclovir prophylaxis).","Neuropatia e herpes-zóster."],["ptnxn4r6m","Mechanism and use of lenalidomide and thalidomide?","Immunomodulatory drugs (cereblon); multiple myeloma, myelodysplasia (5q-).","Imunomoduladores; mieloma."],["1uxeddhh4","Mechanism of checkpoint inhibitors?","Monoclonal antibodies blocking PD-1 (pembrolizumab, nivolumab), PD-L1 (atezolizumab), or CTLA-4 (ipilimumab), enhancing T-cell antitumor responses.","Bloqueiam PD-1, PD-L1 ou CTLA-4."],["1kurq8oz8","Adverse effects of checkpoint inhibitors?","Immune-related adverse events: colitis, pneumonitis, hepatitis, endocrinopathies (thyroiditis, hypophysitis, adrenal insufficiency), dermatitis.","Inflamações autoimunes em vários órgãos."],["h7him03vw","Mechanism and use of all-trans retinoic acid?","Induces differentiation of promyelocytes in APL.","Diferencia os promielócitos."],["12oabbe17","Adverse effect of ATRA in APL?","Differentiation syndrome (fever, respiratory distress, edema).","Síndrome de diferenciação."],["anezp41gn","Mechanism and use of rasburicase?","Recombinant urate oxidase converting uric acid to allantoin; tumor lysis syndrome. Contraindicated in G6PD deficiency.","Degrada ácido úrico; não usar na G6PD."],["qo8xpwro9","Mechanism of leucovorin?","Folinic acid that bypasses DHFR, rescuing normal cells from methotrexate toxicity (and enhances 5-FU).","Resgate do metotrexato."],["8kqk64516","Mechanism of mesna?","Binds acrolein (toxic metabolite of cyclophosphamide/ifosfamide), preventing hemorrhagic cystitis.","Neutraliza acroleína."],["7hwd0l1hf","Mechanism of dexrazoxane?","Iron chelator preventing anthracycline cardiotoxicity.","Protege o coração das antraciclinas."],["s9fgm91ox","Mechanism of amifostine?","Free radical scavenger reducing cisplatin nephrotoxicity.","Protege o rim da cisplatina."],["nlt2y218u","Mechanism and use of filgrastim and sargramostim?","Recombinant G-CSF and GM-CSF; recovery of bone marrow (neutropenia after chemotherapy).","Estimulam neutrófilos."],["gj70di1wr","Mechanism and use of epoetin alfa?","Recombinant erythropoietin; anemia of CKD and chemotherapy; risk of hypertension and thrombosis.","Eritropoetina; risco de trombose."],["1r2jxbo1u","Mechanism and use of romiplostim and eltrombopag?","Thrombopoietin receptor agonists; ITP and aplastic anemia.","Agonistas da trombopoetina."],["1dcqox1cs","Mechanism of heparin?","Activates antithrombin, decreasing thrombin and factor Xa; monitored with PTT.","Ativa a antitrombina."],["uq6lxzeho","Advantages of LMWH over unfractionated heparin?","Better bioavailability, longer half-life, subcutaneous dosing without routine monitoring, less HIT.","Mais previsível e menos HIT."],["31k9j71vm","Mechanism of fondaparinux?","Synthetic pentasaccharide that potentiates antithrombin inhibition of factor Xa only.","Inibe só o Xa via antitrombina."],["uvonyjyjc","Mechanism of warfarin?","Inhibits vitamin K epoxide reductase (VKORC1), decreasing factors II, VII, IX, X, C, S; monitored with PT/INR.","Antagoniza a vitamina K."],["1kgohmt57","Which drugs increase the effect of warfarin?","CYP2C9 inhibitors: amiodarone, fluconazole, metronidazole, TMP-SMX, acetaminophen (high dose); also antibiotics that reduce gut vitamin K.","Amiodarona, fluconazol, metronidazol, sulfa."],["14gq3oj1y","Which drugs decrease the effect of warfarin?","CYP inducers: rifampin, carbamazepine, phenytoin, St. John's wort; vitamin K-rich foods.","Rifampicina, carbamazepina, fenitoína."],["1ece0ez1p","Is warfarin safe in pregnancy?","No; teratogenic (crosses placenta); use heparin or LMWH instead.","Não; usar heparina."],["6cgmm3ghg","Mechanism of direct thrombin inhibitors?","Directly inhibit thrombin: argatroban, bivalirudin (IV), dabigatran (oral).","Inibem a trombina diretamente."],["1n4czd217","Mechanism of direct factor Xa inhibitors?","Directly bind and inhibit factor Xa: apixaban, rivaroxaban, edoxaban.","Inibem o fator Xa."],["1qk2kdb1a","Reversal of dabigatran and Xa inhibitors?","Dabigatran: idarucizumab. Xa inhibitors: andexanet alfa (or PCC).","Idarucizumabe; andexanete alfa."],["z4b81jnhx","Mechanism and use of alteplase?","Recombinant tPA converting plasminogen to plasmin; acute MI, ischemic stroke, massive PE.","Trombolítico; ativa plasminogênio."],["1t2ubw01k","Mechanism of aminocaproic acid and tranexamic acid?","Inhibit plasminogen activation (antifibrinolytics); used for bleeding and thrombolytic reversal.","Antifibrinolíticos."],["1jiwft31b","Mechanism of aspirin as antiplatelet?","Irreversibly acetylates COX-1 and COX-2, decreasing thromboxane A2; effect lasts the life of the platelet.","Inibe COX de forma irreversível."],["1so2qzm1v","Mechanism of ADP receptor inhibitors?","Clopidogrel, prasugrel, ticagrelor, ticlopidine block P2Y12, preventing GpIIb/IIIa expression.","Bloqueiam o receptor P2Y12."],["7r8x5gqf8","Adverse effect of ticlopidine?","Neutropenia (and TTP).","Neutropenia."],["1g2dpacnc","Mechanism of dipyridamole and cilostazol?","PDE3 inhibitors increasing cAMP in platelets, inhibiting aggregation; vasodilators.","Inibem a PDE3."],["1gxesod1g","Mechanism of GpIIb/IIIa inhibitors?","Abciximab, eptifibatide, tirofiban bind GpIIb/IIIa preventing fibrinogen binding.","Bloqueiam a GpIIb/IIIa."],["jkhjtc2zz","Mechanism of deferoxamine, deferasirox, deferiprone?","Iron chelators for iron overload.","Quelantes de ferro."],["nohlbd7qq","Adverse effect of deferiprone?","Agranulocytosis.","Agranulocitose."],["16gyuqp1q","Which chemotherapy drug causes peripheral neuropathy and paralytic ileus?","Vincristine.","Vincristina."],["14usp1k16","Which chemotherapy drugs cause pulmonary fibrosis?","Bleomycin, busulfan, methotrexate, nitrosoureas (carmustine).","Bleomicina e bussulfano."],["ymlgun1gb","Which chemotherapy drug causes hemorrhagic cystitis?","Cyclophosphamide and ifosfamide.","Ciclofosfamida e ifosfamida."],["azxknbevy","Which chemotherapy drug causes ototoxicity?","Cisplatin.","Cisplatina."],["9pcjcx1st","Which chemotherapy drug causes cardiotoxicity?","Anthracyclines (doxorubicin) and trastuzumab.","Doxorrubicina e trastuzumabe."],["13qml7a13","Which drug class causes hand-foot syndrome?","Fluoropyrimidines (5-FU, capecitabine) and some TKIs.","Fluoropirimidinas."],["2kj5i7wmr","Which chemotherapeutic causes severe diarrhea?","Irinotecan (and 5-FU).","Irinotecano."],["14bn8bgsc","Which drug is used for chemotherapy-induced nausea and vomiting?","Ondansetron (5-HT3 antagonist), aprepitant (NK1 antagonist), dexamethasone.","Ondansetrona, aprepitanto e dexametasona."],["1b7u0ni12","Mechanism and use of brentuximab vedotin?","Antibody-drug conjugate against CD30; Hodgkin lymphoma and ALCL.","Anti-CD30; linfoma de Hodgkin."],["t3ei3o199","Mechanism of CAR T-cell therapy?","Patient T cells engineered to express chimeric antigen receptor (e.g., anti-CD19); B-cell lymphomas, ALL; risk of cytokine release syndrome.","Linfócitos T modificados; síndrome de liberação de citocinas."],["1nru571rp","Mechanism and use of ruxolitinib?","JAK1/2 inhibitor; myelofibrosis, polycythemia vera, graft-versus-host disease.","Inibidor de JAK; mielofibrose."]]},{"name":"Physiology","cards":[["rvf8mz14a","What are the steps of primary hemostasis?","Endothelial injury, vasoconstriction, platelet adhesion (vWF to GpIb), platelet activation (ADP, TXA2), platelet aggregation (fibrinogen to GpIIb/IIIa), forming a platelet plug.","Formação do tampão plaquetário."],["1etm0eo1j","What is secondary hemostasis?","Coagulation cascade generates thrombin, converting fibrinogen to fibrin that stabilizes the platelet plug.","Cascata gera fibrina que estabiliza o tampão."],["xbeqvq13m","Which factors are in the extrinsic pathway?","Tissue factor and factor VII; measured by PT.","Fator tecidual e VII; avaliados pelo TP."],["u4wp817gi","Which factors are in the intrinsic pathway?","Factors XII, XI, IX, VIII; measured by PTT.","XII, XI, IX e VIII; avaliados pelo TTPa."],["tqon4p1aw","Which factors form the common pathway?","X, V, II (prothrombin), I (fibrinogen).","X, V, II e I."],["1eiy1e78o","What does thrombin do?","Converts fibrinogen to fibrin, activates factors V, VIII, XI, XIII, and platelets.","Forma fibrina e ativa fatores e plaquetas."],["19081bu1n","What does factor XIII do?","Cross-links fibrin to stabilize the clot (requires Ca2+).","Estabiliza a fibrina."],["1lr5dez15","Which coagulation factors are vitamin K dependent?","II, VII, IX, X, proteins C and S.","II, VII, IX, X, C e S."],["1fv3ybrny","What are the natural anticoagulants?","Antithrombin, protein C, protein S, tissue factor pathway inhibitor.","Antitrombina, proteínas C e S."],["zaqgpv190","What does activated protein C do?","With protein S, inactivates factors Va and VIIIa.","Inativa os fatores Va e VIIIa."],["14xynu77n","What does antithrombin inhibit?","Thrombin (IIa), factor Xa, and to a lesser extent IXa, XIa, XIIa; enhanced by heparin.","Inibe trombina e Xa; potenciada pela heparina."],["1yr2qui1p","What is the fibrinolytic system?","Plasminogen activated by tPA to plasmin, which degrades fibrin and fibrinogen into fibrin split products and D-dimers.","Plasmina degrada fibrina."],["19smdxwh8","What is D-dimer?","Degradation product of cross-linked fibrin; elevated in DVT, PE, DIC; good negative predictive value.","Produto da fibrina; bom para excluir trombose."],["1nggu7b1c","Which factor is produced by endothelial cells rather than the liver?","Factor VIII (and von Willebrand factor).","Fator VIII."],["1qwxhdoee","What does von Willebrand factor do?","Mediates platelet adhesion to collagen (via GpIb) and carries/stabilizes factor VIII.","Adesão plaquetária e transporte do fator VIII."],["1py2qz51j","What does PT measure?","Extrinsic and common pathways: factors I, II, V, VII, X.","Vias extrínseca e comum."],["vknw5h1ux","What does PTT measure?","Intrinsic and common pathways: all factors except VII and XIII.","Vias intrínseca e comum."],["1fvlnaue4","What does bleeding time assess?","Platelet function (primary hemostasis).","Função plaquetária."],["yyc5yexvz","What is the INR?","Standardized PT ratio; used to monitor warfarin.","TP padronizado; controle da varfarina."],["11zujqc1j","What is a mixing study used for?","Distinguishes factor deficiency (PTT corrects) from an inhibitor such as antiphospholipid antibody or factor VIII inhibitor (does not correct).","Diferencia deficiência de inibidor."],["1fku0zp1t","What are the RBC indices MCV and MCHC?","MCV: average RBC volume (micro/normo/macrocytic). MCHC: hemoglobin concentration (high in spherocytosis).","Volume e concentração de hemoglobina."],["yyv642xwc","What is the RDW?","Red cell distribution width: variation in RBC size; increased in iron deficiency and mixed anemias.","Variação do tamanho das hemácias."],["fvk5gamff","What is the reticulocyte production index?","Corrected reticulocyte count accounting for anemia and early release; >2 indicates adequate marrow response.","Índice corrigido de reticulócitos."],["1o69ewrjb","How does hemoglobin bind O2 cooperatively?","Binding of one O2 increases affinity of the others (T to R state), giving a sigmoidal curve.","Ligação cooperativa; curva sigmoide."],["fr9vvc1ov","What shifts the oxygen dissociation curve to the right?","Increased H+ (low pH), CO2, 2,3-BPG, temperature, exercise, altitude. Right shift = unloading.","Ácido, CO2, 2,3-BPG e calor liberam O2."],["1kktcojhf","What is the Bohr effect?","Increased H+ and CO2 decrease hemoglobin O2 affinity, promoting O2 release in tissues.","Ácido e CO2 liberam O2 nos tecidos."],["19w2wbz1w","What is the Haldane effect?","Oxygenation of hemoglobin in the lungs promotes release of CO2 and H+.","Oxigenação libera CO2 nos pulmões."],["1n3s1zouw","What shifts the curve to the left?","Decreased H+, CO2, 2,3-BPG, temperature; HbF; carbon monoxide; methemoglobin.","HbF, CO e metemoglobina prendem O2."],["1lhapq21k","How does carbon monoxide affect oxygen delivery?","Binds Hb with much higher affinity than O2, decreases O2 content, and shifts the curve left.","CO ocupa a hemoglobina e prende O2."],["qr01bs1xi","What is methemoglobin?","Oxidized hemoglobin (Fe3+) that cannot bind O2 well; causes cyanosis with chocolate-colored blood.","Ferro oxidado; sangue cor de chocolate."],["ibgdm81oz","What causes methemoglobinemia?","Oxidizing drugs: nitrites, dapsone, benzocaine/local anesthetics, primaquine; congenital forms.","Nitritos, dapsona, anestésicos locais."],["4mez5xw0x","Treatment of methemoglobinemia?","Methylene blue (and vitamin C).","Azul de metileno."],["8r9pl0vu9","Why is pulse oximetry misleading in CO poisoning?","It reads carboxyhemoglobin as oxyhemoglobin, giving falsely normal SpO2.","Oxímetro dá saturação falsamente normal."],["1atcxg8dm","How is iron transported and stored?","Transported by transferrin; stored as ferritin (and hemosiderin) in macrophages and hepatocytes.","Transferrina transporta; ferritina armazena."],["w7ffti1up","What is TIBC?","Total iron-binding capacity, an indirect measure of transferrin; increased in iron deficiency, decreased in chronic disease.","Medida indireta da transferrina."],["18ml2op1a","What is ferritin's role as a lab test?","Reflects iron stores; low in iron deficiency; acute phase reactant (high in inflammation).","Reflete estoques de ferro; sobe na inflamação."],["rx7a9m8gi","What are ABO blood type antigens and antibodies?","Type A: A antigen, anti-B antibodies; type B: B antigen, anti-A; type AB: both antigens, no antibodies (universal recipient); type O: no antigens, both antibodies (universal donor).","AB recebe de todos; O doa para todos."],["1tlvffv1h","What class of antibody are anti-A and anti-B?","Mostly IgM (do not cross placenta).","Principalmente IgM."],["11nhvqxo1","What is Rh incompatibility?","Rh-negative mother exposed to Rh-positive fetal blood makes anti-D IgG that crosses the placenta in later pregnancies, causing hemolytic disease of the newborn.","Mãe Rh negativo produz anti-D contra o feto."],["1a8d32v9k","How is Rh alloimmunization prevented?","Anti-D immune globulin (RhoGAM) at 28 weeks and after delivery if baby is Rh positive.","Imunoglobulina anti-D."],["1ciw17o1b","Why is ABO hemolytic disease of the newborn milder?","Most anti-A/anti-B are IgM; occurs mainly in type O mothers with IgG, usually mild.","Mais leve; mãe tipo O."],["1mh0sdb1g","What does fresh frozen plasma contain?","All coagulation factors and plasma proteins; used for multiple factor deficiencies and warfarin reversal (when PCC unavailable).","Todos os fatores de coagulação."],["puhr621r3","What does cryoprecipitate contain?","Fibrinogen, factor VIII, factor XIII, vWF, fibronectin; used for hypofibrinogenemia.","Fibrinogênio, VIII, XIII e vWF."],["1773hj81t","What are platelets transfused for?","Bleeding with thrombocytopenia or platelet dysfunction; prophylaxis when counts are very low.","Sangramento com plaquetas baixas."],["1m82t7i1s","What are packed RBCs transfused for?","Acute blood loss and severe anemia; each unit raises Hb by about 1 g/dL.","Cada bolsa sobe 1 g/dL."],["1v6ytq31c","What are risks of massive transfusion?","Hypocalcemia (citrate), hyperkalemia, hypothermia, dilutional coagulopathy, iron overload with chronic use.","Hipocalcemia, hipercalemia, hipotermia."],["qal55eab4","What is the normal platelet count?","150,000-400,000/mm³.","150 a 400 mil."],["rhic1nc6h","At what platelet count does spontaneous bleeding risk rise?","Below about 10,000-20,000/mm³.","Abaixo de 10-20 mil."],["1t89dwu16","What type of bleeding suggests platelet disorders?","Mucocutaneous bleeding: petechiae, epistaxis, gum bleeding, menorrhagia.","Petéquias e sangramento de mucosas."],["1k58a0s1w","What type of bleeding suggests coagulation factor disorders?","Deep tissue bleeding: hemarthroses, muscle hematomas, delayed bleeding after surgery.","Hemartrose e hematomas profundos."],["1xzdr71vf","What is the role of NO and prostacyclin in normal endothelium?","Inhibit platelet aggregation and cause vasodilation.","Inibem plaquetas e dilatam vasos."],["1msds6ui5","What does thromboxane A2 do?","Promotes platelet aggregation and vasoconstriction.","Agrega plaquetas e contrai vasos."],["1gatxtc1k","What does ADP do on platelets?","Binds P2Y12 receptor, inducing GpIIb/IIIa expression and aggregation.","Ativa P2Y12 e a agregação."],["ilum3svkj","What is the role of the spleen in RBC quality control?","Removes old and abnormal RBCs and inclusions (pitting).","Remove hemácias velhas e inclusões."],["1y3w1ymvw","What is extravascular hemolysis?","RBC destruction by macrophages in spleen and liver: jaundice, splenomegaly, increased unconjugated bilirubin.","Destruição no baço; esplenomegalia."],["vabzhwnad","What is intravascular hemolysis?","RBC destruction within vessels: decreased haptoglobin, increased free hemoglobin, hemoglobinuria, hemosiderinuria.","Haptoglobina baixa e hemoglobinúria."],["1qq9yhn1p","What lab findings are common to all hemolysis?","Increased LDH, increased reticulocytes, increased unconjugated bilirubin, decreased haptoglobin.","LDH e reticulócitos altos, haptoglobina baixa."],["159sonapg","What is the Coombs test used for?","Detecting antibodies against RBCs: direct (on RBCs) for autoimmune hemolysis; indirect (in serum) for pretransfusion and prenatal screening.","Detecta anticorpos contra hemácias."],["1kqqh4m1d","What is the role of folate and B12 in hematopoiesis?","Needed for DNA synthesis; deficiency causes megaloblastic changes.","Necessários para o DNA das hemácias."],["1jy5puteh","What is the role of erythropoietin in CKD anemia?","Decreased EPO production causes normocytic anemia; treated with ESA (epoetin).","Falta de EPO na doença renal."],["gnwmwq1x3","What is the role of hepcidin?","Liver hormone that inhibits iron absorption and release from macrophages by degrading ferroportin; increased in inflammation.","Bloqueia o ferro; sobe na inflamação."],["10pdgcf2q","What are the acute phase reactants?","Upregulated: CRP, ferritin, fibrinogen, hepcidin, serum amyloid A, haptoglobin. Downregulated: albumin, transferrin.","PCR, ferritina, fibrinogênio sobem; albumina cai."],["yyfhbrxw2","What is the ESR?","Rate of RBC sedimentation, increased by fibrinogen and other acute phase proteins; nonspecific inflammation marker.","VHS: marcador inespecífico de inflamação."],["isag851ta","What decreases ESR?","Sickle cell disease, polycythemia, hereditary spherocytosis, heart failure, hypofibrinogenemia.","Falciforme, policitemia."],["sap4bue0e","What is hematocrit's relationship to blood viscosity?","Higher hematocrit increases viscosity (polycythemia), increasing thrombosis risk.","Hematócrito alto aumenta viscosidade."],["1ckwhry66","What does the Schilling test historically assess?","Cause of B12 deficiency (pernicious anemia vs malabsorption); replaced by antibody testing.","Causa da falta de B12; histórico."],["9heby8xzs","What are Heinz bodies?","Denatured hemoglobin precipitates (oxidative damage), seen in G6PD deficiency.","Hemoglobina desnaturada; G6PD."],["1ol6q7o1u","What are Howell-Jolly bodies?","Basophilic nuclear remnants in RBCs, seen in asplenia or functional hyposplenism.","Restos nucleares; asplenia."],["qwmjdgall","What are Pappenheimer bodies?","Iron-containing granules in RBCs; seen in sideroblastic anemia.","Grânulos de ferro; anemia sideroblástica."],["doedy8aot","What is basophilic stippling?","Ribosomal precipitates in RBCs: lead poisoning, sideroblastic anemia, thalassemias.","Pontilhado basófilo; chumbo e talassemia."],["i6epk81bx","What are ringed sideroblasts?","Erythroid precursors with iron-laden mitochondria encircling the nucleus (Prussian blue stain), seen in sideroblastic anemia.","Ferro em anel ao redor do núcleo."],["h9bkrr3yk","What are schistocytes?","Fragmented RBCs (helmet cells) from mechanical hemolysis: DIC, TTP/HUS, HELLP, mechanical valves.","Hemácias fragmentadas; hemólise mecânica."]]}];
